// === Tab: mySketch ===
//made by twitter.com/mattywillo_
//for twitter.com/sableRaph's weekly creative coding challenge
//i was working on something else and couldn't finish it before the stream, or at all
//so heres some gradients, squint and it looks like a flower
//this is NOT really the meromorphic function / domain colouring thing
//but something i bumbled into while working on that
//go look at https://twitter.com/mattywillo_/status/1451843306183266306
//instead which is better, but doesn't run on the web

let t = 0, st = .0001, res, sh;

function draw() {
  t+=st*deltaTime;

  sh.setUniform("t", t%1);
  sh.setUniform("l", t|0);
  shader(sh);
  rect(0,0,0);
}

//noprotect
let src = [`
attribute vec3 aPosition;
varying vec2 uv;
void main() {
  gl_Position = vec4(aPosition*2.-1., 1.0);
  uv = vec2(aPosition.x, 1.-aPosition.y)*2.-1.;
}
`,`
precision highp float;
#define PI `+Math.PI+`
varying vec2 uv;
uniform float t,l;

//iq's oklab implentation
vec3 oklab_mix( vec3 colA, vec3 colB, float h )
{
    const mat3 kCONEtoLMS = mat3(0.4121656120,  0.2118591070,  0.0883097947,0.5362752080,  0.6807189584,  0.2818474174,0.0514575653,  0.1074065790,  0.6302613616);
    const mat3 kLMStoCONE = mat3(4.0767245293, -1.2681437731, -0.0041119885,-3.3072168827,  2.6093323231, -0.7034763098,0.2307590544, -0.3411344290,  1.7068625689);
    vec3 lmsA = pow( kCONEtoLMS*colA, vec3(1.0/3.0) );
    vec3 lmsB = pow( kCONEtoLMS*colB, vec3(1.0/3.0) );
    vec3 lms = mix( lmsA, lmsB, h );
    lms *= 1.0+0.2*h*(1.0-h);
    return kLMStoCONE*(lms*lms*lms);
}

vec2 d(vec2 a, vec2 b) {return vec2(((a.x*b.x+a.y*b.y)/(b.x*b.x+b.y*b.y)),(a.y*b.x-a.x*b.y)/(b.x*b.x+b.y*b.y));}

void main() {
  vec2 p = uv;
  vec2 l = vec2(1), j = vec2(1), k = vec2(1);
  for(float i = 0.; i <= 1.; i+=.1) {
    float ct = (mod(floor(t*2.),2.)==0.)?i*t:1.-(i-i*t);
    float cs = (mod(floor(mod(t+.5,1.)*2.),2.)==0.)?i*mod(t+.5,1.):1.-(i-i*mod(t+.5,1.));
    vec2 a = vec2(sin(ct*PI*4.), cos(ct*PI*4.))*.2;
    vec2 b = -a;
    l = d(l,d(p-a,p-b));
    j = d(j,d(p-vec2(sin(i*PI*2.), cos(i*PI*4.))*.5,p-b));
    k = d(k,d(p-vec2(sin(cs*PI*4.), cos(ct*PI*2.))*.6,p-b));
  }
  float d = .5*atan(l.y,l.x)/PI+.5;
  float e = .5*atan(j.y,j.x)/PI+.5;
  float f = .5*atan(k.y,k.x)/PI+.5;
  gl_FragColor = vec4(oklab_mix(oklab_mix(oklab_mix(vec3(162,180,255)/255.,vec3(109,104,112)/255.,e-d),vec3(130,205,255)/255.,e-d), oklab_mix(1.-vec3(104,109,120)/255.,1.-vec3(121,220,240)/255.,e), f-e),1.);
}`];

function setup() {
  res = Math.max(windowWidth, windowHeight);
  createCanvas(1112, 834, WEBGL);
  sh = new p5.Shader(undefined, ...src);
}

function windowResized() {
  res = max(windowWidth, windowHeight);
  resizeCanvas(width, height);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

